/** The application models the conversions use: a copy of the classes DB2CRUD read. */

export enum ProductStatus {
  Draft = 'draft',
  Live = 'live',
}

/** Customer, as the application has it. */
export interface Customer {
  id: number
  email: string
  passwordHash: string
  createdAt: Date
}

/** CategoryDto, as the application has it. */
export interface CategoryDto {
  id: number
  name: string
}

/** Product, as the application has it. */
export interface Product {
  id: number
  name: string
  price: string
  status: ProductStatus
  categoryName: string
  tagIds: number[]
  description?: string
}

/** TagEntity, as the application has it. */
export interface TagEntity {
  id: number
  label: string
}

