/** Conversions between the application models and the "categories" table: what the service takes and returns. */
import type { CategoryDto } from '../application-models.js'
import type { CategoryCreate, CategoryRead } from '../dtos/category.js'

/** A CategoryDto as the categories table takes it. */
export function categoryDtoToCategoryCreate(model: CategoryDto): CategoryCreate {
  return {
    name: model.name,
  }
}

/** A row of the categories table as a CategoryDto. */
export function categoryReadToCategoryDto(row: CategoryRead): CategoryDto {
  return {
    id: row.id,
    name: row.name,
  }
}

