/** Conversions between the application models and the "customers" table: what the service takes and returns. */
import type { Customer as CustomerModel } from '../application-models.js'
import type { CustomerCreate, CustomerRead } from '../dtos/customer.js'

/** A Customer as the customers table takes it. */
export function customerModelToCustomerCreate(model: CustomerModel): CustomerCreate {
  return {
    email: model.email,
    passwordHash: model.passwordHash,
  }
}

/** A row of the customers table as a Customer. */
export function customerReadToCustomerModel(row: CustomerRead): CustomerModel {
  return {
    id: row.id,
    email: row.email,
    // TODO: passwordHash: the service never returns it (password_hash)
    passwordHash: undefined as never,
    createdAt: row.createdAt,
  }
}

files.src/conversions/product.ts:
/** Conversions between the application models and the "products" table: what the service takes and returns. */
import type { Product as ProductModel, ProductStatus } from '../application-models.js'
import type { ProductCreate, ProductRead } from '../dtos/product.js'
import { NotFoundError } from '../errors.js'
import type { UnitOfWork } from '../unit-of-work.js'

/** A Product as the products table takes it. */
export async function productModelToProductCreate(model: ProductModel, uow: UnitOfWork): Promise<ProductCreate> {
  const category = await uow.categories.findByName(model.categoryName)
  if (!category) throw new NotFoundError('Category', model.categoryName)
  return {
    categoryId: category.id,
    name: model.name,
    price: model.price,
    status: String(model.status),
  }
}

/** A row of the products table as a Product. */
export async function productReadToProductModel(row: ProductRead, uow: UnitOfWork): Promise<ProductModel> {
  const category = await uow.categories.findById(row.categoryId)
  return {
    id: row.id,
    name: row.name,
    price: row.price,
    status: (row.status as ProductStatus),
    categoryName: category!.name,
    tagIds: (await uow.productTags.listByProductId(row.id)).map((item) => item.tagId),
  }
}

