    return { id: entity.id, categoryId: entity.categoryId, name: entity.name, price: entity.price, status: entity.status }
  }

  /** Stores a new Product after checking it. */
  async createProduct(data: ProductCreate): Promise<ProductRead> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(data).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      await this.check(uow, values, null)
      const created = await uow.products.insert(Object.assign(new Product(), values))
      return ProductService.read(created)
    })
  }

  /** The Product with this key; NotFoundError when there is none. */
  async getProduct(id: number): Promise<ProductRead> {
    return ProductService.read(await this.find(this.uow, id))
  }

  /** A page of products, by primary key. */
  async listProducts(offset = 0, limit = 50): Promise<Page<ProductRead>> {
    const page = await this.uow.products.list(offset, limit)
    return { ...page, items: page.items.map((entity) => ProductService.read(entity)) }
  }

  /** Changes the given values of a Product. */
  async updateProduct(id: number, data: ProductUpdate): Promise<ProductRead> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(data).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      await this.check(uow, values, current)
      Object.assign(current, values)
      const updated = await uow.products.update(current)
      return ProductService.read(updated)
    })
  }

  /** Deletes a Product. */
  async deleteProduct(id: number): Promise<void> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      if ((await uow.productTags.listByProductId(current.id)).length > 0) throw new ConflictError('Product', 'rows of product_tags still point to it', ['product_tags'])
      await uow.products.delete(current)
    })
  }

  /** The products with this category_id. */
  async listProductsByCategoryId(categoryId: number): Promise<ProductRead[]> {
    return (await this.uow.products.listByCategoryId(categoryId)).map((entity) => ProductService.read(entity))
  }

  /** Links a Product and a Tag (product_tags). */
  async addTag(productId: number, tagId: number): Promise<void> {
    return this.uow.transaction(async (uow) => {
      await this.find(uow, productId)
      if ((await uow.tags.findById(tagId)) === null) throw new NotFoundError('Tag', tagId)
